/**
 * Multi-path icons from the Figma exports (docs/figma/exports/petrock-main/*.svg, Iconly/Two-tone) plus the glyphs redrawn
 * from the Figma vector boxes (bottom nav) and the Services tiles (provisional line art from Services.png until the
 * Design System export arrives). Each icon keeps its own square viewBox (16 / 18 / 20 / 24 / 28) and renders at any
 * size; colours are `currentColor` unless a layer has a fixed fill (the nav paw disc). GENERATED by the conversion
 * script in docs/prompts/0010-design-fidelity-part-a.md - edit the hand-drawn entries here, re-run for the exports.
 */
export interface IconPath {
  d: string;
  /** Stroke the path (line icon) instead of filling it. */
  stroke?: boolean;
  /** Stroke width in viewBox units (defaults to the Icon strokeWidth scaled to the box). */
  sw?: number;
  evenodd?: boolean;
  opacity?: number;
  /** Fixed colour layer (multi-colour glyphs); default currentColor. */
  fill?: string;
  /** stroke-dasharray for perforations. */
  dash?: string;
}
export interface IconSvg { viewBox: string; paths: IconPath[]; /** Line-art glyph: obeys the Icon strokeWidth. */ line?: boolean; source?: string }

